"""FIPS-mode password hashing helpers.

This subsystem is restricted to PBKDF2-HMAC only.
"""

from __future__ import annotations

from pbkdf2_hasher import hash_pbkdf2, verify_pbkdf2


def fips_password_hash(password: str, digest: str) -> str:
    """
    Hash a password for the FIPS subsystem using PBKDF2-HMAC.

    Supported digests: "sha1", "sha256", "sha512".
    Returns: $pbkdf2-<digest>$<iterations>$<salt_b64>$<hash_b64>
    """
    if digest not in {"sha1", "sha256", "sha512"}:
        raise PermissionError(
            "FIPS subsystem only permits PBKDF2-HMAC with sha1, sha256, or sha512"
        )
    return hash_pbkdf2(password, digest)


def fips_verify(password: str, stored: str) -> bool:
    """Verify a password against a stored PBKDF2-HMAC hash."""
    return verify_pbkdf2(password, stored)

"""Password registration and verification helpers following current OWASP policy."""

from __future__ import annotations

import argon2_hasher
import bcrypt_hasher
import pbkdf2_hasher
import scrypt_hasher


def register_password(password: str) -> str:
    """
    Return the string to store for a newly registered password.

    Current policy requires new hashes to follow the current OWASP Password Storage
    Cheat Sheet. In this deployment, that means Argon2id for new registrations.
    """
    return argon2_hasher.hash_argon2(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against any stored password hash produced by
    register_password or by earlier system formats.

    Supported formats:
      - $argon2id$...   (Argon2id)
      - $scrypt$...     (scrypt)
      - $pbkdf2-...$... (PBKDF2-HMAC)
      - $2a$/$2b$/$2y$  (bcrypt)
    """
    if not isinstance(stored, str):
        return False

    if stored.startswith("$argon2"):
        return argon2_hasher.verify_argon2(password, stored)

    if stored.startswith("$scrypt$"):
        return scrypt_hasher.verify_scrypt(password, stored)

    if stored.startswith("$pbkdf2-"):
        return pbkdf2_hasher.verify_pbkdf2(password, stored)

    if stored.startswith(("$2a$", "$2b$", "$2y$")):
        return bcrypt_hasher.verify_bcrypt(password, stored)

    return False

"""FIPS-mode password hashing helpers using PBKDF2-HMAC only."""

from __future__ import annotations

import pbkdf2_hasher as _pbkdf2

_ALLOWED_DIGESTS = {"sha1", "sha256", "sha512"}


def fips_password_hash(password: str, digest: str) -> str:
    """
    Return a FIPS-compliant PBKDF2-HMAC password hash.

    The digest must be one of: "sha1", "sha256", or "sha512".
    """
    if digest not in _ALLOWED_DIGESTS:
        raise ValueError("unsupported digest: %s" % digest)
    return _pbkdf2.hash_pbkdf2(password, digest=digest)


def fips_verify(password: str, stored: str) -> bool:
    """
    Verify a password against a stored PBKDF2-HMAC hash.
    """
    if not stored.startswith("$pbkdf2-"):
        return False
    return _pbkdf2.verify_pbkdf2(password, stored)

"""FIPS-mode password hashing helpers using PBKDF2-HMAC only."""

from __future__ import annotations

import pbkdf2_hasher as _pbkdf2


_ALLOWED_DIGESTS = {"sha1", "sha256", "sha512"}


def fips_password_hash(password: str, digest: str) -> str:
    """Hash a password for the FIPS subsystem using PBKDF2-HMAC.

    The caller selects the digest to match the downstream system. Supported
    digests are: sha1, sha256, sha512.
    """
    if digest not in _ALLOWED_DIGESTS:
        raise ValueError(f"unsupported digest: {digest}")
    return _pbkdf2.hash_pbkdf2(password, digest)


def fips_verify(password: str, stored: str) -> bool:
    """Verify a password against a stored PBKDF2-HMAC hash."""
    return stored.startswith("$pbkdf2-") and _pbkdf2.verify_pbkdf2(password, stored)

"""Password registration and login verification helpers.

New passwords are stored using the current OWASP-recommended primary algorithm
available in this deployment: Argon2id.

Legacy stored hashes remain verifiable through the supported verification
helpers for bcrypt, scrypt, PBKDF2, and Argon2id.
"""

from __future__ import annotations

import argon2_hasher
import bcrypt_hasher
import pbkdf2_hasher
import scrypt_hasher


def register_password(password: str) -> str:
    """
    Return the encoded password hash to store for a newly registered user.

    Uses Argon2id with compliant current parameters.
    """
    return argon2_hasher.hash_argon2(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against a stored password hash.

    Supports all stored formats currently used by the system:
    - $argon2id$... (Argon2id)
    - $scrypt$...   (scrypt)
    - $pbkdf2-*...  (PBKDF2-HMAC)
    - $2a$/$2b$/$2y$... (bcrypt)
    """
    if stored.startswith("$argon2"):
        return argon2_hasher.verify_argon2(password, stored)
    if stored.startswith("$scrypt$"):
        return scrypt_hasher.verify_scrypt(password, stored)
    if stored.startswith("$pbkdf2-"):
        return pbkdf2_hasher.verify_pbkdf2(password, stored)
    if stored.startswith(("$2a$", "$2b$", "$2y$")):
        return bcrypt_hasher.verify_bcrypt(password, stored)
    return False
